mapper.select:
select
knowledge.*
from knowledge knowledge
left join types types on knowledge.type_id = types.id

    and knowledge.id = #{id}
    and knowledge.banner_img = #{bannerImg}
    and knowledge.type_id = #{typeId}
    and knowledge.content = #{content}
    and knowledge.info = #{info}
    and knowledge.create_time = #{createTime}
    and knowledge.title like concat('%',#{title},'%')


    limit #{current},#{pageSize}

select count(*) from knowledge knowledge
left join types types on knowledge.type_id = types.id

    and knowledge.id = #{id}
    and knowledge.banner_img = #{bannerImg}
    and knowledge.type_id = #{typeId}
    and knowledge.content = #{content}
    and knowledge.info = #{info}
    and knowledge.create_time = #{createTime}
    and knowledge.title like concat('%',#{title},'%')
